const S={view:'logs',file:null,opened:[],scope:'all',search:'',flags:{case:false,whole:false,regex:false},level:'',software:'',fn:'',module:'',queryHits:null,searching:false,searchError:'',rules:[],ruleMode:'or',ruleTab:0,page:1,pageSize:60,precision:load('precision','sec'),theme:load('theme','ink'),compact:load('compact',false),wrap:false,sidebar:true,timeline:true,timelineTab:'events',tlOnlyIssues:false,selected:null,expanded:new Set(),bodyModes:{},fullFields:new Set(),bookmarks:new Set(),draft:{start:null,end:null,keys:[]},applied:null,folded:new Set(),inspector:null,inspectorTab:'fields',contextSize:100,contextUnit:'lines',recents:load('ranges',[]),favoriteOnly:false,libSource:'server',folder:'',libQuery:'',libSelected:new Set(),folderOpen:true,collapsedDirs:new Set(),profiles:load('profiles',baseProfiles),profile:'cpq',ruleSection:'nodes',profileTrash:false,nodeRules:load('nodes',defaultNodes),dirty:false,testResult:null,colorOverrides:load('colors',{}),users:[]};
